use vstd::prelude::*;

verus! {
    fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>)
        ensures
            a.len() == result.0.len() + result.1.len(),
            // concatenation of result.0 and result.1 equals original a
            a@ == result.0@ + result.1@,
            // if length > 1, each returned vector is strictly shorter
            (a.len() > 1 ==> (result.0.len() < a.len() && result.1.len() < a.len()))
    {
        if a.len() <= 1 {
            // If a is empty or has one element, just put all elements in the first vector
            // and second is empty, this trivially satisfies conditions.
            (a, Vec::new())
        } else {
            // length > 1
            // split at midpoint (floor division)
            let mid = a.len() / 2;
            // first vector: elements 0..mid
            let first = a.slice(0, mid);
            // second vector: elements mid..len
            let second = a.slice(mid, a.len());

            // verify: lengths add up
            assert(first.len() + second.len() == a.len());

            // verify: concatenation of slices is original
            assert(a@ == first@ + second@);

            // verify: both shorter than original length
            assert(first.len() < a.len());
            assert(second.len() < a.len());

            (first, second)
        }
    }
}

